<?php
 namespace QQWorld\UrlRewrite\Model\Storage; use QQWorld\Framework\Api\DataObjectHelper; use QQWorld\Framework\App\ResourceConnection; use QQWorld\UrlRewrite\Model\OptionProvider; use QQWorld\UrlRewrite\Service\V1\Data\UrlRewrite; use QQWorld\UrlRewrite\Service\V1\Data\UrlRewriteFactory; use Psr\Log\LoggerInterface; use QQWorld\UrlRewrite\Service\V1\Data\UrlRewrite as UrlRewriteData; class DbStorage extends AbstractStorage { const TABLE_NAME = 'url_rewrite'; const ERROR_CODE_DUPLICATE_ENTRY = 1062; protected $connection; protected $resource; private $logger; public function __construct( UrlRewriteFactory $urlRewriteFactory, DataObjectHelper $dataObjectHelper, ResourceConnection $resource, LoggerInterface $logger = null ) { $this->connection = $resource->getConnection(); $this->resource = $resource; $this->logger = $logger ?: \QQWorld\Framework\App\ObjectManager::getInstance() ->get(\Psr\Log\LoggerInterface::class); parent::__construct($urlRewriteFactory, $dataObjectHelper); } protected function prepareSelect(array $data) { $select = $this->connection->select(); $select->from($this->resource->getTableName(self::TABLE_NAME)); foreach ($data as $column => $value) { $select->where($this->connection->quoteIdentifier($column) . ' IN (?)', $value); } return $select; } protected function doFindAllByData(array $data) { return $this->connection->fetchAll($this->prepareSelect($data)); } protected function doFindOneByData(array $data) { if (array_key_exists(UrlRewrite::REQUEST_PATH, $data) && is_string($data[UrlRewrite::REQUEST_PATH]) ) { $result = null; $requestPath = $data[UrlRewrite::REQUEST_PATH]; $data[UrlRewrite::REQUEST_PATH] = [ rtrim($requestPath, '/'), rtrim($requestPath, '/') . '/', ]; $resultsFromDb = $this->connection->fetchAll($this->prepareSelect($data)); if (count($resultsFromDb) === 1) { $resultFromDb = current($resultsFromDb); $redirectTypes = [OptionProvider::TEMPORARY, OptionProvider::PERMANENT]; $canReturnResultFromDb = ($resultFromDb[UrlRewrite::REQUEST_PATH] === $requestPath || in_array((int)$resultFromDb[UrlRewrite::REDIRECT_TYPE], $redirectTypes, true)); $result = $canReturnResultFromDb ? $resultFromDb : [ UrlRewrite::ENTITY_TYPE => 'custom', UrlRewrite::ENTITY_ID => '0', UrlRewrite::REQUEST_PATH => $requestPath, UrlRewrite::TARGET_PATH => $resultFromDb[UrlRewrite::REQUEST_PATH], UrlRewrite::REDIRECT_TYPE => OptionProvider::PERMANENT, UrlRewrite::STORE_ID => $resultFromDb[UrlRewrite::STORE_ID], UrlRewrite::DESCRIPTION => null, UrlRewrite::IS_AUTOGENERATED => '0', UrlRewrite::METADATA => null, ]; } else { foreach ($resultsFromDb as $resultFromDb) { if ($resultFromDb[UrlRewrite::REQUEST_PATH] === $requestPath) { $result = $resultFromDb; break; } } } return $result; } return $this->connection->fetchRow($this->prepareSelect($data)); } protected function doReplace(array $urls) { foreach ($this->createFilterDataBasedOnUrls($urls) as $type => $urlData) { $urlData[UrlRewrite::ENTITY_TYPE] = $type; $this->deleteByData($urlData); } $data = []; foreach ($urls as $url) { $data[] = $url->toArray(); } try { $this->insertMultiple($data); } catch (\QQWorld\Framework\Exception\AlreadyExistsException $e) { $urlConflicted = []; foreach ($urls as $url) { $urlFound = $this->doFindOneByData( [ UrlRewriteData::REQUEST_PATH => $url->getRequestPath(), UrlRewriteData::STORE_ID => $url->getStoreId() ] ); if (isset($urlFound[UrlRewriteData::URL_REWRITE_ID])) { $urlConflicted[$urlFound[UrlRewriteData::URL_REWRITE_ID]] = $url->toArray(); } } if ($urlConflicted) { throw new \QQWorld\UrlRewrite\Model\Exception\UrlAlreadyExistsException( __('URL key for specified store already exists.'), $e, $e->getCode(), $urlConflicted ); } else { throw $e->getPrevious() ?: $e; } } return $urls; } protected function insertMultiple($data) { try { $this->connection->insertMultiple($this->resource->getTableName(self::TABLE_NAME), $data); } catch (\Exception $e) { if (($e->getCode() === self::ERROR_CODE_DUPLICATE_ENTRY) && preg_match('#SQLSTATE\[23000\]: [^:]+: 1062[^\d]#', $e->getMessage()) ) { throw new \QQWorld\Framework\Exception\AlreadyExistsException( __('URL key for specified store already exists.'), $e ); } throw $e; } } protected function createFilterDataBasedOnUrls($urls) { $data = []; foreach ($urls as $url) { $entityType = $url->getEntityType(); foreach ([UrlRewrite::ENTITY_ID, UrlRewrite::STORE_ID] as $key) { $fieldValue = $url->getByKey($key); if (!isset($data[$entityType][$key]) || !in_array($fieldValue, $data[$entityType][$key])) { $data[$entityType][$key][] = $fieldValue; } } } return $data; } public function deleteByData(array $data) { $this->connection->query( $this->prepareSelect($data)->deleteFromSelect($this->resource->getTableName(self::TABLE_NAME)) ); } } 